# -*- coding: utf-8 -*-
"""Скрытый режим обновления: отчёт кассы → запрос боту «обнови карточку товара МойСклада».

Телефон лежит на складе, его товар в МойСкладе уже есть, а данных диагностики в карточке нет
(у прежних товаров АКБ записана диапазоном, нет циклов, цвета, заключения). Касса читает
телефон по кабелю и просит бота найти товар по IMEI и обновить его доп. поля.

Здесь — только сборка запроса из отчёта, без сети и без Qt, чтобы правила проверялись
тестами. В МойСклад ходит бот Оценки (`deploy/оценка_бот/ms_card_update.py`): ключ у него.
Запрос едет тем же путём, что и запрос автоцены (касса → сервер → таблица обмена → бот), и
отличается ключом `мойсклад`.

Значения полей — те же, что касса кладёт в сделку (`ocenka.посылка`): диапазон и точный
процент батареи, циклы, память, цвет словом словаря, SIM-лоток, panic full. Отличие одно —
состояние: в сделке его выбирает сотрудник, а здесь сотрудник телефон не описывает, поэтому
состояние уходит, только когда кабель сам нашёл заменённую деталь или неродную батарею.
"""
from __future__ import annotations

from datetime import datetime

from . import ocenka

ВЕРСИЯ = 1
НАЙТИ, ЗАПИСАТЬ = "найти", "записать"


def находка(rep: dict) -> tuple:
    """Что кабель нашёл такого, что меняет состояние товара. → (phone_status | None, причина).

    Состояние меняет только заменённая деталь и неродная батарея — так обещано владельцу.
    Остальные находки (замки, паника ядра, чёрный список) в состояние не идут, но причина
    возвращается: она попадёт в «Отчёт диагностики»."""
    rep = rep or {}
    статус, причина = ocenka.переклассифицировать("норма", rep, None)
    if статус != ocenka.СТАТУС_РЕМОНТ:
        return None, ""
    деталь = (rep.get("детали_вердикт") or {}).get("итог") in ("замена", "ремонт")
    батарея = bool((rep.get("батарея") or {}).get("подделка"))
    return (ocenka.СТАТУС_РЕМОНТ if (деталь or батарея) else None), str(причина or "")


def поля(rep: dict, *, точка: str = "", ссылка_чека: str = "", когда: datetime | None = None,
         тест: dict | None = None, ручная: dict | None = None, сотрудник: str = "") -> dict:
    """Что отчёт говорит про товар — словами и ключами сделки Оценки. Чего кабель не прочитал,
    того в словаре нет вовсе (None): пустым значением заполненное поле товара не затирают."""
    rep = rep or {}
    пас, бат = rep.get("паспорт") or {}, rep.get("батарея") or {}
    здоровье, циклы = бат.get("здоровье_%"), бат.get("циклы")
    статус, причина = находка(rep)
    откуда = f"Киоск {точка} от {(когда or datetime.now()):%Y-%m-%d}".replace("  ", " ")
    ссылка = str(ссылка_чека or "").strip()
    return {
        "akb": ocenka.акб_для_оценки(здоровье, циклы) if здоровье is not None else None,
        "akb_exact": здоровье,
        "akb_cycles": циклы,
        "ddr": (rep.get("память") or {}).get("объём_гб"),
        "color": ocenka.цвет_для_оценки(пас.get("цвет")),
        "sim": ocenka.sim_для_оценки(пас) if ocenka.лоток_определён(пас) else None,
        "panic_full": (rep.get("паника") or {}).get("panic_full"),
        "phone_status": статус,
        "comment_ocenka": ocenka.комментарий_оценщика(
            rep, откуда=откуда, состояние="Товар со склада" if причина else "", почему=причина),
        "ссылка_чека": ссылка if ссылка.startswith("https://") and len(ссылка) <= 300 else "",
        # когда читали телефон — для галочки «Прошёл диагностику» и поля с датой в карточке
        # товара. Берём время из слепка, а не «сейчас»: товар мог читаться и до отправки.
        "когда_диагностика": str(rep.get("когда") or "") or f"{когда or datetime.now():%Y-%m-%d %H:%M:%S}",
        # все доп. поля карточки, которыми владеет диагностика: имя поля МойСклада → значение.
        # None значит «очистить» — бот перезаполняет их заменой, а не дописыванием.
        "доп": доп_поля(rep, тест=тест, ручная=ручная, сотрудник=сотрудник,
                        когда=str(rep.get("когда") or "") or f"{когда or datetime.now():%Y-%m-%d %H:%M:%S}"),
    }


def запрос(rep: dict, код: str, *, что: str = НАЙТИ, номер: str = "", товар: str = "",
           точка: str = "", ссылка_чека: str = "", тест: dict | None = None,
           ручная: dict | None = None, сотрудник: str = "") -> dict:
    """Запрос боту. `что` — «найти» (показать, что изменится) или «записать» (после
    подтверждения сотрудника; `товар` — id товара, который ему показывали). `номер` — по нему
    касса узнаёт ответ на свой последний вопрос."""
    пас = (rep or {}).get("паспорт") or {}
    имеи = [str(x).strip() for x in (пас.get("imei"), пас.get("imei2")) if str(x or "").strip()]
    return {
        "версия": ВЕРСИЯ,
        "код": str(код or ""),
        "запрос_цены": str(номер or ""),
        "точка": точка or "",
        "модель": str(пас.get("модель") or "")[:50],
        "imei": list(dict.fromkeys(имеи)),
        "мойсклад": {"что": ЗАПИСАТЬ if что == ЗАПИСАТЬ else НАЙТИ, **({"товар": str(товар)} if товар else {})},
        "поля": поля(rep, точка=точка, ссылка_чека=ссылка_чека, тест=тест, ручная=ручная,
                     сотрудник=сотрудник),
    }


# ---------------------------------------------------------------- доп. поля карточки товара
# 18.11.2026 владелец завёл в МойСкладе поле на каждую сущность диагностики (100 — предел
# тарифа) и велел: «пусть он не дописывает, не корректирует. А все доп поля перезаполняет
# заменой». Отсюда два правила, и оба важны:
#
#   1. В словаре `доп_поля` ключ есть ВСЕГДА, даже когда значения нет. `None` означает
#      «очистить поле», а не «не трогать»: иначе замена вырождается в дописывание, а в
#      карточке остаётся прошлое значение от другого телефона.
#   2. В словаре есть ТОЛЬКО наши поля. Kaspi, Halyk, скидку, артикул, бренд, способ
#      приобретения, комплектацию и номер сделки ведут люди и другие процессы — их имён
#      здесь нет вовсе, поэтому замена до них не дотянется.
#
# Отдельно не очищаем никогда (их читает Pay и прайс, пустота там дороже неточности):
# «Imei 1», «АКБ», «Память», «Статус», «Цвет» — они идут прежним путём, через `поля()`.

# Имя поля → (имена в «детали_вердикт», имена в «сигналы»). Названия деталей у вердикта и у
# сверки привязки разные («Аккумулятор» против «Деталь: Акб», «Камера» против «Основная
# камера»), поэтому сопоставление явное, а не по совпадению строк.
ДЕТАЛИ_ПОЛЯ = (
    ("Деталь: Акб", ("Аккумулятор",), ()),
    ("Деталь: Экран", ("Экран",), ("Экран: калибровка",)),
    ("Деталь: Стекло экрана", (), ("Экран: стекло ↔ панель",)),
    ("Деталь: Тачскрин", (), ("Тачскрин",)),
    ("Деталь: Face ID", ("Face ID",), ("Face ID ↔ плата",)),
    ("Деталь: Taptic Engine", ("Taptic Engine",), ("Taptic ↔ плата",)),
    ("Деталь: Датчик приближения", ("Датчик приближения",), ("Датчик приближения",)),
    ("Деталь: Основная камера", ("Камера", "Основная камера"), ("Основная камера",)),
    ("Деталь: Сверхширокая камера", ("Сверхширокая камера",), ("Сверхширокая",)),
    ("Деталь: Телефото камера", ("Телефото камера",), ()),
    ("Деталь: Фронтальная камера", ("Фронтальная камера",), ("Фронтальная",)),
    ("Деталь: LiDAR", ("LiDAR",), ()),
    ("Деталь: Плата", ("Плата", "Материнская плата"), ()),
    ("Деталь: Заднее стекло", ("Заднее стекло",), ()),
    ("Деталь: Корпус", ("Корпус", "Верхний модуль"), ()),
)
# Пункты теста на телефоне и ручной анкеты: ключ ответа → имя поля МойСклада.
ТЕСТ_ПОЛЯ = (("sensor", "Тест: Сенсор"), ("multitouch", "Тест: Мультитач"),
             ("screen", "Тест: Экран"), ("speaker", "Тест: Динамики"),
             ("mic", "Тест: Микрофон"), ("camera_back", "Тест: Камера сзади"),
             ("camera_front", "Тест: Камера спереди"))
РУЧНЫЕ_ПОЛЯ = (("keys", "Ручное: Кнопки"), ("vibro", "Ручное: Вибрация"),
               ("bio", "Ручное: Face ID"), ("charge", "Ручное: Зарядка"),
               ("net", "Ручное: Связь"), ("glue", "Ручное: Герметик"),
               ("apple", "Ручное: Детали Apple"), ("mdm", "Ручное: Управление"))
ДЛИНА_ТЕКСТА = 4000
ДЛИНА_СТРОКИ = 255


def _деталь_родная(вердикт: dict, сигналы: dict, имена_в: tuple, имена_с: tuple):
    """Деталь родная? True / False / None (данных нет).

    Сначала вердикт по деталям: он один знает про замену (журнал Apple и кабель вместе).
    Потом сверка привязки по кабелю, где у сигнала «ок» три состояния, и `null` — это
    «не прочиталось», а не «родная»."""
    по_имени = {str(d.get("деталь") or ""): d for d in (вердикт.get("детали") or [])}
    for имя in имена_в:
        d = по_имени.get(имя)
        if d and d.get("статус"):
            return d["статус"] == "ok"
    for имя in имена_с:
        с = (сигналы or {}).get(имя)
        if isinstance(с, dict) and с.get("ок") is not None:
            return bool(с["ок"])
    return None


def _ответ(значение):
    """Ответ теста или анкеты → галочка. «Пропуск» и пустое — None, иначе соврём «не прошло»."""
    if значение is True or значение is False:
        return значение
    з = str(значение or "").strip().lower()
    if з in ("ok", "да", "true", "1"):
        return True
    if з in ("fail", "нет", "false", "0"):
        return False
    return None


def _строка(значение, предел=ДЛИНА_СТРОКИ):
    т = str(значение).strip() if значение not in (None, "") else ""
    return т[:предел] or None


def _коды_деталей(rep: dict):
    """Коды изготовителя всех деталей — одним текстовым полем.

    Отдельных полей на каждый код не хватило (тариф даёт 100 доп. полей), а код нужен для
    спора с клиентом и для сверки с чеком сервиса. В одном поле типа «текст» 4000 знаков —
    тринадцати кодов с именами деталей хватает с запасом."""
    строки = []
    for d in (rep.get("детали") or []):
        имя = str(d.get("деталь") or "").strip()
        куски = [str(d.get(к) or "").strip() for к in ("производитель", "фабрика", "серийник")]
        куски = [к for к in куски if к]
        if имя and куски:
            строки.append(f"{имя}: {' · '.join(куски)}")
    return _строка("\n".join(строки), ДЛИНА_ТЕКСТА)


def _память_подробно(rep: dict):
    """Внутренности памяти одним текстом: на отдельные поля места в тарифе нет."""
    пам, нанд = rep.get("память") or {}, rep.get("nand") or {}
    пары = (("контроллер NVMe", пам.get("nvme_модель")), ("прошивка NVMe", пам.get("nvme_прошивка")),
            ("производитель NAND", пам.get("nand_производитель")), ("тип ячейки", пам.get("nand_тип")),
            ("маркировка NAND", пам.get("nand_маркировка")),
            ("объём по контроллеру, ГБ", пам.get("nvme_объём_гб")),
            ("записей NANDInfo", нанд.get("записей")),
            ("прошивка совпала с NVMe", нанд.get("прошивка_совпала_с_nvme")))
    return _строка("\n".join(f"{и}: {з}" for и, з in пары if з not in (None, "")), ДЛИНА_ТЕКСТА)


def доп_поля(rep: dict, *, тест: dict | None = None, ручная: dict | None = None,
             сотрудник: str = "", когда=None) -> dict:
    """Все доп. поля карточки товара, которыми владеет диагностика: имя поля → значение.

    Ключ присутствует всегда; `None` значит «очистить». Имён чужих полей здесь нет —
    замена до них не дотянется. `тест` и `ручная` — отметки теста на телефоне и анкеты
    сотрудника теми же ключами, что в сделке; не передали — соответствующие поля очистятся,
    потому что для ЭТОГО телефона их не снимали.
    """
    пас = rep.get("паспорт") or {}
    бат = rep.get("батарея") or {}
    пам = rep.get("память") or {}
    пан = rep.get("паника") or {}
    прав = rep.get("правовой") or {}
    вердикт = rep.get("детали_вердикт") or {}
    сигналы = rep.get("сигналы") or {}
    рфс = rep.get("рфс") or []
    ск = rep.get("sickw") or {}

    out: dict = {}

    # --- детали: галочка на каждую, и сводные строки рядом
    # 18.11.2026 карточку сжали (73 поля → 47), но шестнадцать галочек по деталям владелец
    # оставил: в одном товаре такая отметка стояла руками, и они дороже свободных мест.
    # Деталь, про которую в ЭТОТ проход не сказал ни один канал, не трогаем вовсе — её имени
    # в словаре нет. Это не поблажка, а защита от потери: часть деталей (плата, корпус,
    # заднее стекло, верхний модуль, LiDAR) известна ТОЛЬКО из журнала Apple, а журнал
    # открывают на телефоне клиента при выкупе. В режиме обновления телефон со склада, раздел
    # Apple никто не открывает — и сплошная замена стёрла бы ровно то, что записали при
    # выкупе. Непрочитанное при этом не прячется: его перечисляет «Детали: не прочитано».
    по_деталям = {}
    for поле_имя, имена_в, имена_с in ДЕТАЛИ_ПОЛЯ:
        ок = _деталь_родная(вердикт, сигналы, имена_в, имена_с)
        по_деталям[поле_имя.removeprefix("Деталь: ")] = ок
        if ок is not None:
            out[поле_имя] = ок
    память_сошлась = пам.get("объём_сошёлся")
    по_деталям["Память"] = память_сошлась
    if память_сошлась is not None:
        out["Деталь: Память"] = память_сошлась
    out["Детали: вердикт"] = _строка(вердикт.get("итог"))
    out["Детали: подтвердила Apple"] = (bool(вердикт.get("apple_подтверждено"))
                                        if вердикт.get("итог") else None)
    находки = [f"{d.get('деталь')}: {d.get('почему')}" for d in (вердикт.get("детали") or [])
               if d.get("статус") and d["статус"] != "ok"]
    # и те детали, по которым кабель сам увидел несоответствие: раньше это было видно по
    # галочке «Деталь: …», теперь галочек нет — значит обязано попасть в строку
    находки += [f"{имя}: привязка не сошлась" for имя, ок in по_деталям.items() if ок is False
                and not any(имя in н for н in находки)]
    out["Детали: находки"] = _строка("; ".join(находки))
    не_прочитаны = [имя for имя, ок in по_деталям.items() if ок is None]
    out["Детали: не прочитано"] = _строка(
        "; ".join(x for x in (вердикт.get("почему"),
                              ("нет данных: " + ", ".join(не_прочитаны)) if не_прочитаны else "")
                  if x))
    out["Коды деталей"] = _коды_деталей(rep)

    # --- тест на телефоне и анкета сотрудника: ЗАМЕНА ПОБЛОЧНО
    #
    # Замена поблочная, и это не отступление от правила «перезаполнять, а не дописывать», а
    # его единственное работающее прочтение. Кабель читает телефон каждый проход, поэтому
    # его поля заменяются всегда. Тест на телефоне и анкету сотрудника в этот проход могли
    # не снимать вовсе — тогда ключей этого блока в словаре НЕТ, и бот их не трогает.
    # Иначе повторное чтение одним кабелем стирало бы тест, снятый на прошлой неделе:
    # данные, которые владелец и просил собирать.
    #
    # Внутри блока правило прежнее и строгое: сняли тест — заменяются ВСЕ его поля, и пункт,
    # который сотрудник пропустил, очищается. «Пропуск» — это не «не прошло» и не «прошло».
    провалы, снято = [], []
    if тест is not None:
        ответы = {имя: _ответ(тест.get(ключ)) for ключ, имя in ТЕСТ_ПОЛЯ}
        снято.append("тест")
        провалы += [и.removeprefix("Тест: ") for и, о in ответы.items() if о is False]
        # Словами, а не галочками: пятнадцать полей на тест и анкету карточка не держит
        # (предел тарифа 100), а в одной строке видно и что прошло, и что пропущено.
        out["Тест: итог"] = _строка(
            " · ".join(f"{и.removeprefix('Тест: ')}: "
                       + {True: "работает", False: "НЕ работает"}.get(о, "не проверяли")
                       for и, о in ответы.items())
            + (f" · когда: {когда}" if когда else ""), ДЛИНА_ТЕКСТА)
    if ручная is not None:
        отметки = {имя: _ответ(ручная.get(ключ)) for ключ, имя in РУЧНЫЕ_ПОЛЯ}
        снято.append("руки")
        провалы += [и.removeprefix("Ручное: ") for и, о in отметки.items() if о is False]
        out["Ручное: итог"] = _строка(
            " · ".join(f"{и.removeprefix('Ручное: ')}: "
                       + {True: "в порядке", False: "НЕ в порядке"}.get(о, "не отмечено")
                       for и, о in отметки.items())
            + (f" · проверял: {сотрудник}" if сотрудник else ""), ДЛИНА_ТЕКСТА)
    # Галочка для фильтра. «Да» ставим только когда сняли ОБА блока и ничего не провалилось:
    # «все проверки прошли» при непройденном тесте было бы неправдой на витрине. Сняли один
    # блок или ничего — поле очищается, а подробности видны в строках выше.
    if провалы:
        out["Все проверки прошли"] = False
    elif len(снято) == 2:
        out["Все проверки прошли"] = True
    elif снято:
        out["Все проверки прошли"] = None

    # --- батарея
    out["АКБ: процент"] = бат.get("здоровье_%") or бат.get("здоровье_по_телефону_%")
    out["АКБ: ёмкость, мА·ч"] = бат.get("ёмкость_мАч")
    out["АКБ: заводская ёмкость, мА·ч"] = бат.get("заводская_мАч")
    # наработка, макс. температура, снятия шлейфа и «процент назвал телефон» убраны из
    # карточки 18.11.2026 — они в базе диагностики, в снимке и отчёте
    # дату выпуска батарея не печатает в своём разделе — она есть в списке деталей, у записи
    # про аккумулятор (поле «дата»): это дата изготовления детали из её серийника
    out["АКБ: дата выпуска"] = next(
        (d.get("дата") for d in (rep.get("детали") or [])
         if str(d.get("деталь") or "") == "Аккумулятор" and d.get("дата")), None)
    out["АКБ: требует обслуживания (Apple)"] = (bool(бат.get("обслуживание_флаг"))
                                                if бат.get("обслуживание_флаг") is not None else None)

    # --- память
    out["Память: объём сошёлся"] = пам.get("объём_сошёлся")
    out["Память: объём по контроллеру"] = пам.get("nvme_объём_гб")
    out["Память: подробно"] = _память_подробно(rep)

    # --- паспорт
    out["Паспорт: серийный номер"] = _строка(пас.get("серийник"))
    out["Паспорт: код модели"] = _строка(пас.get("код_модели"))
    out["Паспорт: номер модели"] = _строка(пас.get("номер_модели") or пас.get("номер_a"))
    out["Паспорт: регион продажи"] = _строка(пас.get("регион"))
    # MEID, серийник платы, сборка iOS, версия модема, чип, UDID, ECID и выпуск убраны из
    # карточки: это данные для сервиса и для спора, их никто не фильтрует. Лежат в базе.
    out["Паспорт: iOS"] = _строка(пас.get("ios"))
    out["Паспорт: только eSIM"] = (bool(пас.get("esim_only"))
                                   if пас.get("esim_only") is not None else None)

    # --- верификация IMEI в реестре РК (РФС)
    for номер, поле_имя in ((0, "Верификация IMEI 1"), (1, "Верификация IMEI 2")):
        запись = рфс[номер] if len(рфс) > номер and isinstance(рфс[номер], dict) else None
        # у ответа реестра человеческая строка в `status_text` («Верифицирован»), код — в
        # `verdict`; если реестр не ответил, поле очищается, а не врёт «не верифицирован»
        out[поле_имя] = _строка((запись or {}).get("status_text") or (запись or {}).get("verdict"))

    # --- паники
    out["Паника: паник всего"] = пан.get("паник_всего")
    out["Паника: полных отчётов"] = пан.get("полных")

    # --- замки
    out["Замок: MDM (надзор)"] = _строка(прав.get("mdm"))
    # чёрный список и блокировку оператора знает только внешняя база (Sickw): по кабелю их
    # не видно вовсе. База не ответила — поля очищаются, иначе прошлый ответ про ДРУГОЙ
    # телефон остался бы в карточке и читался как проверенный.
    out["Замок: чёрный список"] = _строка(ск.get("чёрный_список"))
    out["Замок: блокировка оператора"] = _строка(ск.get("sim_lock") or ск.get("оператор"))

    # --- гарантия
    out["Гарантия Apple до"] = ск.get("гарантия_до")
    out["Дата первой покупки"] = ск.get("дата_покупки") or ск.get("активация")

    return out
